describe('Email Inline Validation', () => {
  beforeEach(() => {
    cy.visit('/contact');
  });

  it('should display inline validation errors as user types in email field', () => {
    // Intercept the API call to validate email
    cy.intercept('POST', '/api/validate-email', {
      statusCode: 200,
      body: {
        isValid: false,
        errors: ['Email must be at least 6 characters long']
      }
    }).as('validateEmail');

    // Get the email input field
    cy.get('[data-testid="email-input"]').should('be.visible');

    // Type a valid email
    cy.get('[data-testid="email-input"]').type('test@example.com');
    cy.get('[data-testid="email-input"]').should('have.value', 'test@example.com');

    // Verify validation error is not displayed
    cy.get('[data-testid="email-error-message"]').should('not.exist');

    // Clear the email field
    cy.get('[data-testid="email-input"]').clear();

    // Type an invalid email
    cy.get('[data-testid="email-input"]').type('t');

    // Verify validation error is displayed
    cy.get('[data-testid="email-error-message"]').should('be.visible');
    cy.get('[data-testid="email-error-message"]').should('contain', 'Email must be at least 6 characters long');

    // Verify error message disappears when valid email is entered
    cy.get('[data-testid="email-input"]').type('valid@example.com');
    cy.get('[data-testid="email-error-message"]').should('not.exist');

    // Verify API call was made
    cy.wait('@validateEmail');
  });

  it('should clear validation errors when email is corrected', () => {
    // Intercept the API call to validate email
    cy.intercept('POST', '/api/validate-email', {
      statusCode: 200,
      body: {
        isValid: false,
        errors: ['Email must be at least 6 characters long']
      }
    }).as('validateEmail');

    // Get the email input field
    cy.get('[data-testid="email-input"]').should('be.visible');

    // Type an invalid email
    cy.get('[data-testid="email-input"]').type('invalid');

    // Verify validation error is displayed
    cy.get('[data-testid="email-error-message"]').should('be.visible');
    cy.get('[data-testid="email-error-message"]').should('contain', 'Email must be at least 6 characters long');

    // Clear the email field
    cy.get('[data-testid="email-input"]').clear();

    // Type a valid email
    cy.get('[data-testid="email-input"]').type('valid@example.com');

    // Verify validation error is cleared
    cy.get('[data-testid="email-error-message"]').should('not.exist');

    // Verify API call was made
    cy.wait('@validateEmail');
  });
});
